// the table list the relationship between K, iLS and Zc
static uint16_t K_table[16][3]={
//  K, iLS, Zc
    { 32, 0, 4}, { 64, 0, 8}, {128, 0, 16}, {256, 0, 32},
    {320, 2, 40}, {400, 6, 52}, {480, 7, 60}, {640, 4, 72},
    {800, 2, 80}, {960, 1, 96}, {1280,0, 128},{3840,1,384},
    {256, 0, 32}, {384, 1, 48}, {512, 0, 64}, {768,2,80}
};


//the function return Zc and Vij_array based on K and iLS
void get_LDPC_parameters(int16_t K, uint16_t *Zc, uint8_t **Vij_array)
{
    uint16_t m;
    for (m = 0; m < sizeof(K_table)/sizeof(K_table[0]); m++)
    {
        if (K_table[m][0] == K)
        {
            *Zc = K_table[m][2];
            int16_t iLS = K_table[m][1];
            *Vij_array = BG2_HBG_Vij_array[iLS];
            
            return;
        }
    }
}
